/// Allows direct manual memory injection from the Memory dashboard tab.
#[tauri::command]
pub async fn add_custom_memory_item(memory: String, user_id: String) -> Result<(), String> {
    let mem0_type = get_setting_internal("mem0_type")
        .unwrap_or(None)
        .unwrap_or_else(|| "cloud".to_string());
    
    let mem0_url = get_setting_internal("mem0_url")
        .unwrap_or(None)
        .unwrap_or_else(|| "https://api.mem0.ai".to_string());

    let api_key = get_key("mem0").ok().flatten();

    if api_key.is_none() && mem0_type == "cloud" {
        return Err("API Key is required for Mem0 Cloud mode.".to_string());
    }

    let client = reqwest::Client::new();
    let url = if mem0_type == "cloud" {
        format!("{}/v3/memories/add/", mem0_url.trim_end_matches('/'))
    } else {
        format!("{}/memories", mem0_url.trim_end_matches('/'))
    };

    let payload = json!({
        "user_id": user_id,
        "messages": [
            {
                "role": "user",
                "content": memory
            }
        ]
    });

    let mut req = client.post(&url).header("Content-Type", "application/json");
    req = apply_sidecar_auth(req, &mem0_type);
    if let Some(ref key) = api_key {
        if !key.is_empty() {
            req = req.header("Authorization", format!("Token {}", key));
        }
    }

    let response = req.json(&payload).send().await.map_err(|e| e.to_string())?;

    if !response.status().is_success() {
        let err_text = response.text().await.unwrap_or_default();
        return Err(format!("Mem0 API Error: {}", err_text));
    }

    // Mirror memory to Supabase DB and backup Chroma DB zip to Storage
    let user_id_clone = user_id.to_string();
    let memory_clone = memory.clone();
    tauri::async_runtime::spawn(async move {
        let _ = crate::storage::supabase::insert_memory_to_supabase(&user_id_clone, "semantic", &memory_clone).await;
        crate::storage::supabase::sync_all_to_cloud_async(None, None).await;
    });

    Ok(())
}
